exercises.solution:
def pilih_k(s, ambang):
    total = sum(x * x for x in s)
    berjalan = 0.0
    for i, x in enumerate(s, start=1):
        berjalan += x * x
        if berjalan / total >= ambang - 1e-12:
            return i
    return len(s)

