def penyimpanan(m, n, k):
    kompres = k * (m + n + 1)
    asli = m * n
    return (kompres, asli, round(kompres / asli, 4))

import math

def galat_peringkat(s, k):
    return round(math.sqrt(sum(x * x for x in s[k:])) + 0.0, 4)

